// Package config provides multi-provider configuration loading for agent.
// Supports named providers, environment variable expansion, and compatibility
// with the old flat config format.
package config

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	_ "github.com/DocumentDrivenDX/fizeau/internal/provider/anthropic"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/limits"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/lmstudio"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/lucebox"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/ollama"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/omlx"
	_ "github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openrouter"
	provregistry "github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/vllm"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/safefs"
	"github.com/DocumentDrivenDX/fizeau/internal/sampling"
	"github.com/DocumentDrivenDX/fizeau/telemetry"
	"gopkg.in/yaml.v3"
)

// ProviderConfig describes a single named provider.
type ProviderConfig struct {
	Type      string             `yaml:"type"`               // "openai", "openrouter", "lmstudio", "omlx", "lucebox", "vllm", "ollama", or "anthropic"
	BaseURL   string             `yaml:"base_url,omitempty"` // shorthand for one endpoint
	Endpoints []ProviderEndpoint `yaml:"endpoints,omitempty"`
	APIKey    string             `yaml:"api_key,omitempty"`
	Model     string             `yaml:"model,omitempty"`
	// ModelPattern is a case-insensitive regex applied to auto-discovered model
	// IDs when Model is empty. The first matching model returned by /v1/models
	// is used. If the pattern matches nothing, the first available model is
	// used as a fallback.
	ModelPattern string            `yaml:"model_pattern,omitempty"`
	Headers      map[string]string `yaml:"headers"` // extra HTTP headers (OpenRouter, Azure)
	// Reasoning controls model-side reasoning with one scalar value.
	Reasoning reasoning.Reasoning `yaml:"reasoning,omitempty"`
	// MaxTokens is the maximum number of tokens the model may generate per turn.
	// Zero means use the provider's default.
	MaxTokens int `yaml:"max_tokens,omitempty"`
	// ContextWindow is the model's context window in tokens. Used to configure
	// automatic compaction: the compactor triggers when message history approaches
	// this limit. Zero means use the compaction package default (8192).
	ContextWindow int `yaml:"context_window,omitempty"`
	// Sampling overrides the harness defaults for sampling parameters.
	// Any nil/unset field falls through to harness/server defaults.
	Sampling *SamplingProfile `yaml:"sampling,omitempty"`
	// DailyTokenBudget caps total tokens (request + response) the provider
	// may consume per UTC daily window. Zero/absent disables predictive
	// exhaustion for this provider; the actual quota signal from the
	// upstream API is still respected. See fizeau-f2661619.
	DailyTokenBudget int `yaml:"daily_token_budget,omitempty"`
}

// SamplingProfile is the canonical sampling-overrides bundle. The type
// itself lives in internal/sampling so model-catalog entries and provider
// config can share it without a circular import; this alias preserves the
// existing config.SamplingProfile spelling for callers.
type SamplingProfile = sampling.Profile

// ProviderEndpoint describes one serving endpoint for providers that can run
// across multiple host:port locations.
type ProviderEndpoint struct {
	Name    string `yaml:"name,omitempty"`
	BaseURL string `yaml:"base_url"`
}

// EndpointConfig describes one endpoint-first serving target. Unlike
// ProviderConfig, endpoint blocks do not require a user-facing provider name
// or a configured model; routing discovers live model IDs from /v1/models.
type EndpointConfig struct {
	Name      string              `yaml:"name,omitempty"`
	Type      string              `yaml:"type"`
	Host      string              `yaml:"host,omitempty"`
	Port      int                 `yaml:"port,omitempty"`
	BaseURL   string              `yaml:"base_url,omitempty"`
	APIKey    string              `yaml:"api_key,omitempty"`
	Headers   map[string]string   `yaml:"headers,omitempty"`
	Reasoning reasoning.Reasoning `yaml:"reasoning,omitempty"`
}

// ImportMetadata records the last import source for drift detection.
type ImportMetadata struct {
	// Source is the import source ("pi" or "opencode").
	Source string `yaml:"source"`
	// Timestamp is when the import occurred (RFC3339).
	Timestamp string `yaml:"timestamp"`
	// SourceHash is the truncated SHA-256 of the source files.
	SourceHash string `yaml:"source_hash"`
}

// ModelCatalogConfig configures how the shared model catalog is loaded.
type ModelCatalogConfig struct {
	Manifest string `yaml:"manifest,omitempty"`
}

type ToolsConfig struct {
	Bash BashToolConfig `yaml:"bash,omitempty"`
}

// SkillsConfig configures discovery of SKILL.md progressive-disclosure
// skills.
type SkillsConfig struct {
	// Dir is the skills directory. Empty defaults to ".fizeau/skills"
	// relative to the work directory; "-" disables skill discovery
	// even when a directory exists. The FIZEAU_SKILLS_DIR environment
	// variable overrides this value when set.
	Dir string `yaml:"dir,omitempty"`
}

type BashToolConfig struct {
	OutputFilter BashOutputFilterConfig `yaml:"output_filter,omitempty"`
}

type BashOutputFilterConfig struct {
	Mode         string `yaml:"mode,omitempty"`
	RTKBinary    string `yaml:"rtk_binary,omitempty"`
	MaxBytes     int    `yaml:"max_bytes,omitempty"`
	RawOutputDir string `yaml:"raw_output_dir,omitempty"`
}

// RoutingConfig configures model-first route selection defaults.
type RoutingConfig struct {
	// DefaultModel is the default requested model-route key to use when the
	// caller does not set --model, --model-ref, or --provider.
	DefaultModel string `yaml:"default_model,omitempty"`

	// DefaultModelRef resolves through the model catalog to a canonical route
	// key when no explicit provider or model input is supplied.
	DefaultModelRef string `yaml:"default_model_ref,omitempty"`

	// HealthCooldown controls how long a failed candidate remains deprioritized
	// before it is retried.
	HealthCooldown string `yaml:"health_cooldown,omitempty"`

	// HistoryWindow controls how far back observed routing history is sampled
	// when scoring healthy candidates.
	HistoryWindow string `yaml:"history_window,omitempty"`

	// ProbeTimeout controls provider availability/model probes.
	ProbeTimeout string `yaml:"probe_timeout,omitempty"`

	// ReliabilityWeight weights recent success history when scoring healthy
	// candidates.
	ReliabilityWeight float64 `yaml:"reliability_weight,omitempty"`

	// PerformanceWeight weights observed latency/throughput when scoring healthy
	// candidates.
	PerformanceWeight float64 `yaml:"performance_weight,omitempty"`

	// LoadWeight weights recent selection volume when balancing healthy
	// candidates.
	LoadWeight float64 `yaml:"load_weight,omitempty"`

	// CostWeight weights observed known cost when balancing healthy candidates.
	CostWeight float64 `yaml:"cost_weight,omitempty"`

	// CapabilityWeight weights model benchmark capability (swe_bench_verified)
	// when scoring healthy candidates.
	CapabilityWeight float64 `yaml:"capability_weight"`
}

// BackendPoolConfig describes a named routing target that selects one provider
// before a run using a specified strategy.
type BackendPoolConfig struct {
	// ModelRef is the model catalog reference (alias, profile, or canonical
	// target) attached to this backend pool. Optional.
	ModelRef string `yaml:"model_ref,omitempty"`

	// Providers is the ordered list of named provider references.
	Providers []string `yaml:"providers"`

	// Strategy is the provider selection algorithm: "round-robin" or
	// "first-available". Defaults to "first-available" if empty.
	Strategy string `yaml:"strategy,omitempty"`
}

// ProviderOverrides are per-run overrides applied before building a provider.
type ProviderOverrides struct {
	Model           string
	ModelRef        string
	AllowDeprecated bool
}

const (
	projectConfigDir    = ".fizeau"
	globalConfigDirName = "fizeau"
)

func ProjectConfigDirName() string {
	return projectConfigDir
}

func GlobalConfigDirName() string {
	return globalConfigDirName
}

func DefaultSessionLogDir() string {
	return filepath.Join(projectConfigDir, "sessions")
}

func ProjectConfigPath(workDir string) string {
	return filepath.Join(workDir, projectConfigDir, "config.yaml")
}

func GlobalConfigPath(home string) string {
	return filepath.Join(home, ".config", globalConfigDirName, "config.yaml")
}

func ProjectRouteHealthPath(workDir, routeKey string) string {
	return filepath.Join(workDir, projectConfigDir, "route-health-"+routeKey+".json")
}

func ProjectRouteStateCounterPath(workDir, routeKey string) string {
	return filepath.Join(workDir, projectConfigDir, "route-state-"+routeKey+".counter")
}

func DefaultModelCatalogManifestPath() string {
	configDir, err := os.UserConfigDir()
	if err != nil {
		return ""
	}
	return filepath.Join(configDir, globalConfigDirName, "models.yaml")
}

func FallbackModelCatalogManifestPath() string {
	return filepath.Join(".config", globalConfigDirName, "models.yaml")
}

// Config is the top-level agent configuration.
type Config struct {
	// Providers is a map of named provider configurations.
	Providers map[string]ProviderConfig `yaml:"providers"`

	// Endpoints is the endpoint-first provider schema. Each entry is expanded
	// into an internal generated provider during finalization.
	Endpoints []EndpointConfig `yaml:"endpoints,omitempty"`

	// Routing configures default model-first resolution behavior.
	Routing RoutingConfig `yaml:"routing,omitempty"`

	// Backends is a map of named backend pool configurations.
	Backends map[string]BackendPoolConfig `yaml:"backends,omitempty"`

	// DefaultBackend is the name of the default backend pool. When set, it
	// takes precedence over Default for runs that do not name a provider
	// or backend explicitly.
	DefaultBackend string `yaml:"default_backend,omitempty"`

// Package registry is the single source of truth for provider-type →
// factory mappings.
//
// Why this package exists. Before it, the agent had two parallel
// factories that knew about provider types: internal/config/config.go
// `BuildProvider` (config-time) and service_native_provider.go
// `buildNativeProvider` (service-execute time). When lucebox + vllm
// were added in v0.9.18-.20, only the first factory got the new types;
// the second one rejected requests pinning those providers at execute
// time. Two factories drifting is the architectural smell `agent-8e4eb44c`
// was filed to fix.
//
// Each provider package registers a Descriptor in its init(). Both
// factories call Lookup. New providers are one Register call away from
// being usable through every code path.
//
// The registry deliberately covers only the factory drift case in v1.
// Other type-switch sites (default port, base URL, surface map,
// capability flags, validators) are local to internal/config and
// don't have the cross-package drift problem; they stay there. Future
// drift cases can be additively folded into the registry as they appear.
package registry

import (
	"sort"
	"sync"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/quotaheaders"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Inputs is the canonical factory input shape. Both the config-time
// path (internal/config builds this from a ProviderConfig) and the
// service-time path (service_native_provider builds this from a
// ServiceProviderEntry) populate it. Provider factories take exactly
// one argument so the call sites can't accidentally diverge.
type Inputs struct {
	// ProviderName is the user-facing config name for this provider
	// (e.g., "vidar-omlx"). Distinct from the provider TYPE (e.g.,
	// "omlx"). Some factories include it in attribution metadata.
	ProviderName string

	// BaseURL is the resolved endpoint (with default substituted).
	BaseURL string
	// APIKey is the bearer token; empty for unauthenticated endpoints.
	APIKey string
	// Model is the configured default; empty when discovery is in use.
	Model string

	// ModelPattern is an optional regex used by openai-compat providers
	// during model discovery (Tier-2 ranking).
	ModelPattern string

	// KnownModels maps surface model IDs to canonical IDs from the
	// model catalog. Used by openai-compat providers to recognize
	// catalog-tracked models on a discovery list.
	KnownModels map[string]string

	// Headers is extra HTTP headers (OpenRouter, Azure, custom).
	Headers map[string]string

	// Reasoning is the per-provider default reasoning policy.
	Reasoning reasoning.Reasoning

	// ModelReasoningWire is a model_id → reasoning_wire map sourced
	// from the catalog. Today only openrouter and openai-compat
	// providers consume it; others ignore it.
	ModelReasoningWire map[string]string

	// QuotaSignalObserver, when set, is forwarded to provider factories
	// that support per-response rate-limit-header parsing (anthropic,
	// openai, openrouter). The service layer wires this to the provider
	// quota state machine so dispatch can route around providers whose
	// subscription/daily cap is hit. Providers that do not parse rate-limit
	// headers ignore this field.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// Factory builds a provider from canonical inputs.
type Factory func(Inputs) agentcore.Provider

// Descriptor pairs a provider type with its factory + a small set of
// invariants. Provider packages register these in init().
type Descriptor struct {
	// Type is the canonical provider-type string (e.g., "omlx").
	// Matches the `type:` value in user config and the descriptor's
	// case in internal/config switches.
	Type string

	// Factory builds an agent.Provider from canonical inputs.
	Factory Factory

	// DefaultBaseURL is used by the config-normalizer when no base_url
	// is explicitly set.
	DefaultBaseURL string

	// DefaultPort is used by endpoint-config inference when only a
	// host is supplied. 0 means "no inference; require explicit BaseURL".
	DefaultPort int
}

var (
	mu      sync.RWMutex
	entries = map[string]Descriptor{}
)

// Register installs a provider Descriptor. Called from each provider
// package's init() function. Re-registering the same type panics —
// duplicate registration is always a programmer error.
func Register(d Descriptor) {
	if d.Type == "" {
		panic("provider/registry: Descriptor.Type is required")
	}
	if d.Factory == nil {
		panic("provider/registry: Descriptor.Factory is required for type " + d.Type)
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := entries[d.Type]; exists {
		panic("provider/registry: duplicate registration for type " + d.Type)
	}
	entries[d.Type] = d
}

// Lookup returns the Descriptor for a provider type, or false if the
// type is not registered.
func Lookup(typ string) (Descriptor, bool) {
	mu.RLock()
	defer mu.RUnlock()
	d, ok := entries[typ]
	return d, ok
}

// Types returns all registered provider type names in sorted order.
// Used by validators and conformance descriptors that iterate over
// every known provider type.
func Types() []string {
	mu.RLock()
	defer mu.RUnlock()
	out := make([]string, 0, len(entries))
	for t := range entries {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

