type nativeProviderResolution struct {
	Provider agentcore.Provider
	Name     string
	Entry    ServiceProviderEntry
}

func (s *service) resolveConfiguredNativeProvider(req ServiceExecuteRequest) nativeProviderResolution {
	sc := s.opts.ServiceConfig
	if sc == nil {
		return nativeProviderResolution{}
	}
	name, entry, ok := selectConfiguredNativeProvider(sc, req)
	if !ok {
		return nativeProviderResolution{}
	}
	if req.Model != "" {
		entry.Model = req.Model
	}
	provider := s.buildNativeProvider(name, entry)
	if provider == nil {
		return nativeProviderResolution{Name: name, Entry: entry}
	}
	return nativeProviderResolution{Provider: provider, Name: name, Entry: entry}
}

func selectConfiguredNativeProvider(sc ServiceConfig, req ServiceExecuteRequest) (string, ServiceProviderEntry, bool) {
	if req.Provider != "" {
		if entry, ok := sc.Provider(req.Provider); ok {
			return req.Provider, entry, true
		}
		if name, entry, ok := selectConfiguredEndpointProvider(sc, req.Provider); ok {
			return name, entry, true
		}
	}

	wantedType := requestedNativeProviderType(req)
	if wantedType != "" {
		if name := sc.DefaultProviderName(); name != "" {
			if entry, ok := sc.Provider(name); ok && normalizeServiceProviderType(entry.Type) == wantedType {
				return name, entry, true
			}
		}
		for _, name := range sc.ProviderNames() {
			entry, ok := sc.Provider(name)
			if ok && normalizeServiceProviderType(entry.Type) == wantedType {
				return name, entry, true
			}
		}
	}

	if req.Provider == "" && wantedType == "" {
		name := sc.DefaultProviderName()
		if name == "" {
			return "", ServiceProviderEntry{}, false
		}
		entry, ok := sc.Provider(name)
		return name, entry, ok
	}

	return "", ServiceProviderEntry{}, false
}

func selectConfiguredEndpointProvider(sc ServiceConfig, ref string) (string, ServiceProviderEntry, bool) {
	providerName, endpointName, ok := splitEndpointProviderRef(ref)
	if !ok {
		return "", ServiceProviderEntry{}, false
	}
	entry, ok := sc.Provider(providerName)
	if !ok {
		return "", ServiceProviderEntry{}, false
	}
	for _, endpoint := range modelDiscoveryEndpoints(entry) {
		if endpoint.Name != endpointName {
			continue
		}
		entry.BaseURL = endpoint.BaseURL
		entry.Endpoints = []ServiceProviderEndpoint{{Name: endpoint.Name, BaseURL: endpoint.BaseURL}}
		return ref, entry, true
	}
	return "", ServiceProviderEntry{}, false
}

func endpointProviderRef(providerName, endpointName string) string {
	if endpointName == "" {
		return providerName
	}
	return providerName + "@" + endpointName
}

func splitEndpointProviderRef(ref string) (string, string, bool) {
	providerName, endpointName, ok := strings.Cut(ref, "@")
	if !ok || providerName == "" || endpointName == "" {
		return "", "", false
	}
	return providerName, endpointName, true
}

func requestedNativeProviderType(req ServiceExecuteRequest) string {
	if req.Provider != "" {
		return normalizeServiceProviderType(req.Provider)
	}
	switch req.Harness {
	case "", "agent":
		return ""
	default:
		return normalizeServiceProviderType(req.Harness)
	}
}

func (s *service) nativeProviderNotConfiguredError(req ServiceExecuteRequest, decision RouteDecision) string {
	wantedType := requestedNativeProviderType(req)
	if wantedType == "" {
		errMsg := "orphan model: " + decision.Model
		if decision.Model == "" {
			errMsg = "no provider configured for native harness"
		}
		return errMsg
	}
	available := s.availableProviderTypes()
	harness := decision.Harness
	if harness == "" {
		harness = "agent"
	}
	return fmt.Sprintf("harness %q: no configured provider matches type %q (available: %s)", harness, wantedType, available)
}

func (s *service) availableProviderTypes() string {
	sc := s.opts.ServiceConfig
	if sc == nil {
		return "[]"
	}
	var parts []string
	for _, name := range sc.ProviderNames() {
		entry, ok := sc.Provider(name)
		if !ok {
			continue
		}
		parts = append(parts, fmt.Sprintf("%s (%s)", name, normalizeServiceProviderType(entry.Type)))
	}
	if len(parts) == 0 {
		return "[]"
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// buildNativeProvider is the service-time factory. Per agent-8e4eb44c
// the per-type switch is gone; both this and internal/config's
// BuildProvider go through registry.Lookup. Adding a new provider type
// is one Register() call in the new package; no edits to this file
// or internal/config/config.go's factory.
func (s *service) buildNativeProvider(name string, entry ServiceProviderEntry) agentcore.Provider {
	typ := normalizeServiceProviderType(entry.Type)
	if d, ok := registry.Lookup(typ); ok {
		return d.Factory(registry.Inputs{
			ProviderName:        name,
			BaseURL:             entry.BaseURL,
			APIKey:              entry.APIKey,
			Model:               entry.Model,
			ModelReasoningWire:  nativeModelReasoningWireMap(),
			QuotaSignalObserver: s.quotaSignalObserver(name),
		})
	}
	return nil
}

// quotaSignalObserver returns a callback that updates the provider quota
// state machine when a parsed rate-limit signal indicates the provider's
// subscription/daily cap has been hit (or imminently will be). Returns nil
// when the service has no quota store, which makes the provider middleware
// a no-op.
func (s *service) quotaSignalObserver(providerName string) func(quotaheaders.Signal) {
	if s == nil || s.providerQuota == nil || providerName == "" {
		return nil
	}
	store := s.providerQuota
	return func(signal quotaheaders.Signal) {
		now := time.Now()
		exhausted, retryAt := signal.IsExhausted(now)
		if !exhausted {
			return
		}
		if retryAt.IsZero() {
			// Provider said "exhausted" but gave us no reset window. Fall
			// back to a short cooldown so we don't peg the provider in the
			// excluded set forever; the next response will refresh us.
			retryAt = now.Add(time.Minute)
		}
		store.MarkQuotaExhausted(providerName, retryAt)
	}
}

// nativeModelReasoningWireMap returns the catalog reasoning_wire map for use
// by the native (service-side) provider builder. Models without an explicit
// reasoning_wire are omitted; the provider treats absence as the "provider"
// default.
func nativeModelReasoningWireMap() map[string]string {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil
	}
	all := cat.AllModels()
	if len(all) == 0 {
		return nil
	}
	out := make(map[string]string, len(all))
	for id, entry := range all {
		if entry.ReasoningWire != "" {
			out[id] = entry.ReasoningWire
		}
	}
	return out
}

// Config is the top-level agent configuration.
type Config struct {
	// Providers is a map of named provider configurations.
	Providers map[string]ProviderConfig `yaml:"providers"`

	// Endpoints is the endpoint-first provider schema. Each entry is expanded
	// into an internal generated provider during finalization.
	Endpoints []EndpointConfig `yaml:"endpoints,omitempty"`

	// Routing configures default model-first resolution behavior.
	Routing RoutingConfig `yaml:"routing,omitempty"`

	// Backends is a map of named backend pool configurations.
	Backends map[string]BackendPoolConfig `yaml:"backends,omitempty"`

	// DefaultBackend is the name of the default backend pool. When set, it
	// takes precedence over Default for runs that do not name a provider
	// or backend explicitly.
	DefaultBackend string `yaml:"default_backend,omitempty"`

	// ModelCatalog configures the optional external manifest path.
	ModelCatalog ModelCatalogConfig `yaml:"model_catalog,omitempty"`

	Tools ToolsConfig `yaml:"tools,omitempty"`

	// Anchors enables anchored read output and the anchor_edit tool for CLI runs.
	Anchors bool `yaml:"anchors,omitempty"`

	// Skills configures progressive-disclosure SKILL.md discovery.
	Skills SkillsConfig `yaml:"skills,omitempty"`

	// Telemetry configures OTel export enablement and runtime-specific
	// pricing keyed by provider system and resolved model.
	Telemetry telemetry.Config `yaml:"telemetry,omitempty"`

	// Default is the name of the default provider. If empty, uses the first.
	Default string `yaml:"default"`

	// MaxIterations limits agent loop iterations.
	MaxIterations int `yaml:"max_iterations"`

	// ReasoningByteLimit is the maximum bytes of pure reasoning_content
	// allowed before the stream is aborted. Default is 256KB.
	// Set to 0 for unlimited (same pattern as max_iterations).
	ReasoningByteLimit int `yaml:"reasoning_byte_limit"`

	// CompactionPercent scales the effective context window used to trigger
	// automatic compaction. Range 1-100. 0 or absent = use default (95%).
	// The actual trigger threshold = context_window × percent/100 - reserve_tokens.
	CompactionPercent int `yaml:"compaction_percent,omitempty"`

	// SessionLogDir is where session logs are written.
	SessionLogDir string `yaml:"session_log_dir"`

	// Preset is the system prompt preset name.
	Preset string `yaml:"preset"`

	// ImportedFrom records the last import source for drift detection.
	ImportedFrom *ImportMetadata `yaml:"imported_from,omitempty"`

	// Legacy flat fields for backwards compatibility.
	LegacyProvider string `yaml:"provider,omitempty"`
	LegacyBaseURL  string `yaml:"base_url,omitempty"`
	LegacyAPIKey   string `yaml:"api_key,omitempty"`
	LegacyModel    string `yaml:"model,omitempty"`

	warnings []string `yaml:"-"`
}

// Defaults returns a Config with sensible defaults.
func Defaults() Config {
	return Config{
		MaxIterations:      100,
		SessionLogDir:      DefaultSessionLogDir(),
		Preset:             "default",
		ReasoningByteLimit: agent.DefaultReasoningByteLimit,
	}
}

// Load reads configuration from .fizeau/config.yaml (project) and
// ~/.config/fizeau/config.yaml (global), with env var expansion.
// Project config overrides global config. If no config files exist,
// returns defaults.
func Load(workDir string) (*Config, error) {
	cfg := Defaults()

	// Try global config first, then project config (project wins)
	var paths []string
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, GlobalConfigPath(home))
	}
	paths = append(paths, ProjectConfigPath(workDir))

	for _, p := range paths {
		data, err := safefs.ReadFile(p)
		if err != nil {
			continue
		}
		expanded := expandEnvVars(string(data))
		if err := rejectLegacyProviderReasoningKeys([]byte(expanded)); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
		if err := yaml.Unmarshal([]byte(expanded), &cfg); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
	}

	// Migrate legacy flat format
	cfg.migrateLegacy()

	// Apply env var overrides to default provider
	cfg.applyEnvOverrides()

	if err := cfg.finalize(); err != nil {
		return nil, err
	}

	return &cfg, nil
}

// migrateLegacy converts old flat fields to a named provider.
func (c *Config) migrateLegacy() {
	if c.Providers != nil && len(c.Providers) > 0 {
		return // new format takes precedence
	}
	if c.LegacyProvider == "" && c.LegacyBaseURL == "" {
		return // nothing to migrate
	}

	provType := c.LegacyProvider
	if provType == "" {
		provType = inferProviderTypeFromBaseURL(c.LegacyBaseURL)
		if provType == "" {
			provType = "lmstudio"
		}
	}
	baseURL := c.LegacyBaseURL
	if baseURL == "" {
		baseURL = "http://localhost:1234/v1"
	}

	c.Providers = map[string]ProviderConfig{
		"default": {
			Type:    provType,
			BaseURL: baseURL,
			APIKey:  c.LegacyAPIKey,
			Model:   c.LegacyModel,
		},
	}
	if c.Default == "" {
		c.Default = "default"
	}
	c.LegacyProvider = ""
	c.LegacyBaseURL = ""
	c.LegacyAPIKey = ""
	c.LegacyModel = ""
}

// applyEnvOverrides applies AGENT_* env vars to the default provider.
func (c *Config) applyEnvOverrides() {
	if v := os.Getenv("FIZEAU_SKILLS_DIR"); v != "" {
		c.Skills.Dir = v
	}

	if c.Providers == nil {
		c.Providers = make(map[string]ProviderConfig)
	}

	// Get or create default provider
	defName := c.defaultNameForEnvOverride()
	p := c.Providers[defName]
	changed := false

	if v := os.Getenv("FIZEAU_PROVIDER"); v != "" {
		p.Type = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_BASE_URL"); v != "" {
		p.BaseURL = v
		changed = true

//   - "round-robin": counter % len(providers)
func selectProviderIndex(strategy string, counter, numProviders int) int {
	if numProviders <= 0 {
		return 0
	}
	if strategy == "round-robin" {
		return counter % numProviders
	}
	// first-available and any unknown strategy
	return 0
}

// ResolveBackend resolves a named backend pool to a concrete provider and model.
//
// counter is the rotation index used for round-robin selection; it should be
// the number of prior requests against this backend pool. Callers that want
// stateless first-available behavior can always pass 0.
//
// overrides.Model, when set, bypasses the catalog and uses the given concrete
// model string. overrides.ModelRef, when set, overrides the backend's own
// model_ref. If neither the backend nor the overrides specify a model, the
// provider's configured default model is used.
func (c *Config) ResolveBackend(name string, counter int, overrides ProviderOverrides) (agent.Provider, ProviderConfig, *modelcatalog.ResolvedTarget, error) {
	bc, ok := c.Backends[name]
	if !ok {
		return nil, ProviderConfig{}, nil, fmt.Errorf("config: unknown backend pool %q", name)
	}
	if len(bc.Providers) == 0 {
		return nil, ProviderConfig{}, nil, fmt.Errorf("config: backend pool %q has no providers", name)
	}

	idx := selectProviderIndex(bc.Strategy, counter, len(bc.Providers))
	providerName := bc.Providers[idx]

	// Determine the effective model ref: explicit override takes priority over
	// the backend's own model_ref.
	effectiveOverrides := overrides
	if effectiveOverrides.ModelRef == "" && bc.ModelRef != "" {
		effectiveOverrides.ModelRef = bc.ModelRef
	}

	p, pc, resolved, err := c.BuildProviderWithOverrides(providerName, effectiveOverrides)
	if err != nil {
		return nil, ProviderConfig{}, nil, fmt.Errorf("config: backend pool %q: %w", name, err)
	}

	return p, pc, resolved, nil
}

// buildProviderFromConfig is the config-time factory. Per agent-8e4eb44c
// the per-type switch is gone — both this and service_native_provider's
// buildNativeProvider go through registry.Lookup. Adding a new
// provider type is one Register() call in the new package.
func buildProviderFromConfig(pc ProviderConfig) (agent.Provider, error) {
	pc = normalizeProviderConfig(pc)
	d, ok := provregistry.Lookup(pc.Type)
	if !ok {
		return nil, fmt.Errorf("config: unknown provider type %q", pc.Type)
	}
	return d.Factory(provregistry.Inputs{
		ProviderName:       pc.Type,
		BaseURL:            pc.BaseURL,
		APIKey:             pc.APIKey,
		Model:              pc.Model,
		ModelPattern:       pc.ModelPattern,
		KnownModels:        openAIKnownModels(),
		Headers:            pc.Headers,
		Reasoning:          pc.Reasoning,
		ModelReasoningWire: modelReasoningWireMap(),
	}), nil
}

// LookupModelLimits queries the concrete provider package for provider-owned
// model limits. Unknown or unsupported providers return zero values.
func LookupModelLimits(ctx context.Context, pc ProviderConfig, model string) limits.ModelLimits {
	pc = normalizeProviderConfig(pc)
	switch pc.Type {
	case "openrouter":
		return openrouter.LookupModelLimits(ctx, pc.BaseURL, pc.APIKey, pc.Headers, model)
	case "lmstudio":
		return lmstudio.LookupModelLimits(ctx, pc.BaseURL, model)

		return lmstudio.LookupModelLimits(ctx, pc.BaseURL, model)
	case "omlx":
